argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$branch='agent/bridge-r42-live-control-plane-cutover-20261006';
$sha='0cefcd33eb5b4f75ef52dbe443c2f7395e4ea966';
$tmp=Join-Path $env:TEMP ('webai-r42-cutover-'+$sha+'.ps1');
Set-Location $repo;
& git fetch origin $branch;
if($LASTEXITCODE -ne 0){throw 'git fetch failed'}
$content=& git show ($sha+':app/r42-cutover.ps1');
if($LASTEXITCODE -ne 0){throw 'git show cutover script failed'}
$content | Set-Content -LiteralPath $tmp -Encoding UTF8;
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $tmp -TargetSha $sha -TargetBranch $branch -RepoPath $repo;
$code=$LASTEXITCODE;
if($code -ne 0){throw "R42 cutover exited $code"}
